use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Helper to process a stream and return structured output"] fn process_stream (content : & str , prefix_lines : usize , suffix_lines : usize , max_line_length : usize ,) -> ProcessedStream { let (lines , truncation_info , truncated_lines_count) = clip_by_lines (content , prefix_lines , suffix_lines , max_line_length) ; let total_lines = content . lines () . count () ; let output = tag_output (lines , truncation_info , total_lines , truncated_lines_count) ; ProcessedStream { output , total_lines } }